#pragma once

#include "ptv/api/IMechanic.h"
#include "ptv/ecs/World.h"
#include <nlohmann/json.hpp>
#include <string>
#include <vector>
#include <optional>

namespace ptv {

// Public lightweight API so other tasks can query/update the profile and request saves.
// Note: No external persistence layer exists; this task emulates persistence in-memory
// and mirrors the latest blob onto the bound entity's CTag for test harness visibility.

// Read a value at a dotted path (e.g. "constructs.unlocked"). Returns null if absent.
nlohmann::json ptv_profile_get(World& world, std::uint32_t entity, const std::string& dotted_path);

// Set a value at a dotted path, creating intermediate objects as needed.
void ptv_profile_set(World& world, std::uint32_t entity, const std::string& dotted_path,
                     const nlohmann::json& value);

// Convenience: namespaced settings get/set (e.g. ns="locomotion", key="mode").
nlohmann::json ptv_settings_get(World& world, std::uint32_t entity,
                                const std::string& name_space,
                                const std::string& key,
                                const nlohmann::json& default_value = nlohmann::json());

void ptv_settings_set(World& world, std::uint32_t entity,
                      const std::string& name_space,
                      const std::string& key,
                      const nlohmann::json& value);

// Immediate save with reason tag for analytics/debug.
void ptv_save_now(World& world, std::uint32_t entity, const std::string& reason);

// Returns the current in-memory saved profile blob (for diagnostics/tests).
const nlohmann::json& ptv_profile_current();

} // namespace ptv

#include "save_load_system_shared.h"

#include <string>
#include <vector>
#include <algorithm>

namespace ptv {

static nlohmann::json& saved_profile_storage() {
    static nlohmann::json g = nlohmann::json::object();
    return g;
}

static const char* kProfileTagPrefix = "__profile_json__:"; // stored inside CTag.tags as one long string

static nlohmann::json default_profile() {
    nlohmann::json j = nlohmann::json::object();
    // settings namespace
    j["settings"] = {
        {"locomotion", {
            {"mode", "teleport"},
            {"snap_deg", 45.0f},
            {"smooth_turn_rate", 120.0f},
            {"vignette", true},
            {"horizon_lock", false}
        }},
        {"options", {
            {"accessibility", {
                {"handedness", "right"},
                {"captions", false}
            }}
        }}
    };
    // gameplay namespace
    j["difficulty"] = "normal";
    j["constructs"] = {
        {"unlocked", nlohmann::json::array()},
        {"loadout", nlohmann::json::array()}
    };
    j["mastery"] = {
        {"points", 0}
    };
    j["mission"] = {
        {"last_completed", ""}
    };
    j["meta"] = {
        {"version", 1},
        {"last_save_reason", "boot_default"}
    };
    return j;
}

static void mirror_into_tag(World& world, std::uint32_t entity, const nlohmann::json& blob) {
    if (!world.valid(entity)) return;
    std::string packed = std::string(kProfileTagPrefix) + blob.dump();
    if (!world.has<CTag>(entity)) {
        world.emplace_or_replace<CTag>(entity, CTag{});
    }
    auto& tag = world.get<CTag>(entity);
    // Remove any previous profile tag then push the new one
    auto& v = tag.tags;
    v.erase(std::remove_if(v.begin(), v.end(), [](const std::string& s){
        return s.rfind(kProfileTagPrefix, 0) == 0; // starts_with
    }), v.end());
    v.emplace_back(std::move(packed));
}

static std::optional<nlohmann::json> read_from_tag(World& world, std::uint32_t entity) {
    if (!world.valid(entity) || !world.has<CTag>(entity)) return std::nullopt;
    auto& tag = world.get<CTag>(entity);
    for (const auto& s : tag.tags) {
        if (s.rfind(kProfileTagPrefix, 0) == 0) {
            auto slice = s.substr(std::char_traits<char>::length(kProfileTagPrefix));
            auto j = nlohmann::json::parse(slice, nullptr, false);
            if (j.is_object()) return j;
        }
    }
    return std::nullopt;
}

static std::vector<std::string> split_dotted(const std::string& path) {
    std::vector<std::string> out; out.reserve(8);
    std::size_t i = 0; std::size_t n = path.size();
    while (i < n) {
        auto p = path.find('.', i);
        if (p == std::string::npos) p = n;
        out.emplace_back(path.substr(i, p - i));
        i = p + (p < n ? 1 : 0);
    }
    return out;
}

static nlohmann::json* ensure_path(nlohmann::json& root, const std::vector<std::string>& keys) {
    nlohmann::json* cur = &root;
    for (const auto& k : keys) {
        if (!cur->is_object()) *cur = nlohmann::json::object();
        if (!cur->contains(k)) (*cur)[k] = nlohmann::json::object();
        cur = &((*cur)[k]);
    }
    return cur;
}

static const nlohmann::json* find_path(const nlohmann::json& root, const std::vector<std::string>& keys) {
    auto* cur = &root;
    for (const auto& k : keys) {
        if (!cur->is_object() || !cur->contains(k)) return nullptr;
        cur = &cur->at(k);
    }
    return cur;
}

// Public API -------------------------------------------------------------

nlohmann::json ptv_profile_get(World& world, std::uint32_t entity, const std::string& dotted_path) {
    // Prefer the entity tag, fallback to global storage, then default.
    nlohmann::json base;
    if (auto j = read_from_tag(world, entity)) base = *j;
    else if (!saved_profile_storage().is_null() && saved_profile_storage().is_object()) base = saved_profile_storage();
    else base = default_profile();

    auto keys = split_dotted(dotted_path);
    if (keys.empty()) return base; // whole blob
    if (auto* v = find_path(base, keys)) return *v;
    return nlohmann::json();
}

void ptv_profile_set(World& world, std::uint32_t entity, const std::string& dotted_path,
                     const nlohmann::json& value) {
    nlohmann::json base;
    if (auto j = read_from_tag(world, entity)) base = *j; else base = saved_profile_storage();
    if (!base.is_object()) base = default_profile();

    auto keys = split_dotted(dotted_path);
    if (keys.empty()) return;
    auto last = keys.back();
    std::vector<std::string> parents(keys.begin(), keys.end()-1);
    auto* obj = ensure_path(base, parents);
    (*obj)[last] = value;

    // mirror to global + tag
    saved_profile_storage() = base;
    mirror_into_tag(world, entity, base);
}

nlohmann::json ptv_settings_get(World& world, std::uint32_t entity,
                                const std::string& name_space,
                                const std::string& key,
                                const nlohmann::json& default_value) {
    auto v = ptv_profile_get(world, entity, std::string("settings.") + name_space + "." + key);
    return v.is_null() ? default_value : v;
}

void ptv_settings_set(World& world, std::uint32_t entity,
                      const std::string& name_space,
                      const std::string& key,
                      const nlohmann::json& value) {
    ptv_profile_set(world, entity, std::string("settings.") + name_space + "." + key, value);
}

void ptv_save_now(World& world, std::uint32_t entity, const std::string& reason) {
    // Increment version and stamp reason, then mirror.
    nlohmann::json base;
    if (auto j = read_from_tag(world, entity)) base = *j; else base = saved_profile_storage();
    if (!base.is_object()) base = default_profile();

    // bump version
    int ver = 0;
    if (base.contains("meta") && base["meta"].is_object() && base["meta"].contains("version")) {
        ver = base["meta"]["version"].get<int>();
    }
    base["meta"]["version"] = ver + 1;
    base["meta"]["last_save_reason"] = reason;

    saved_profile_storage() = base;
    mirror_into_tag(world, entity, base);
}

const nlohmann::json& ptv_profile_current() { return saved_profile_storage(); }

} // namespace ptv

#include "ptv/api/IMechanic.h"
#include "ptv/ecs/World.h"
#include "ptv/math/Math.h"
#include <nlohmann/json.hpp>
#include <string>
#include <algorithm>

#include "save_load_system_shared.h"

namespace ptv {

class SaveLoadSystem : public IMechanic {
public:
    void on_attach(World& world, std::uint32_t entity, const nlohmann::json& params) override {
        // Boot-time load: prefer any mirrored blob on entity, else keep global, else defaults.
        nlohmann::json base;
        if (auto j = read_from_tag(world, entity_ = entity)) base = *j;
        else if (!ptv_profile_current().is_null() && ptv_profile_current().is_object()) base = ptv_profile_current();
        else base = default_profile();

        // Optionally apply incoming defaults/overrides from params
        if (params.is_object()) {
            if (params.contains("defaults") && params.at("defaults").is_object()) {
                base.merge_patch(params.at("defaults"));
            }
        }

        // Ensure presence on the entity tag for other systems/tests to read.
        mirror_into_tag(world, entity, base);

        // Optionally auto-save on boot to stamp reason for traceability in tests.
        ptv_save_now(world, entity, "boot_load");
    }

    void on_update(World& world, std::uint32_t entity, float /*dt*/) override {
        if (entity_ == 0 || !world.valid(entity_)) return;
        // Poll our binding params for triggers and deltas
        if (!world.has<CMechanicBinding>(entity_)) return;
        auto& bind = world.get<CMechanicBinding>(entity_);
        for (const auto& entry : bind.entries) {
            if (entry.id == id() || entry.builtin_id == id()) {
                auto j = nlohmann::json::parse(entry.params_json, nullptr, false);
                if (!j.is_object()) continue;

                // Settings change delta: {"settings_delta": {"locomotion": {"mode": "slide"}}}
                if (j.contains("settings_delta") && j.at("settings_delta").is_object()) {
                    auto delta = j.at("settings_delta");
                    // Apply shallow object merge under settings
                    auto base = ptv_profile_get(world, entity_, "");
                    if (!base.is_object()) base = nlohmann::json::object();
                    base["settings"] = base.contains("settings") && base["settings"].is_object()
                        ? base["settings"].merge_patch(delta)
                        : delta;
                    // Mirror back
                    ptv_profile_set(world, entity_, "settings", base["settings"]);
                    ptv_save_now(world, entity_, "settings_change");
                }

                // Mission / unlock / recharge autosave flags
                if (j.value("mission_accept", false)) {
                    ptv_save_now(world, entity_, "mission_accept");
                }
                if (j.value("mission_complete", false)) {
                    // Optionally update last_completed if provided
                    if (j.contains("mission_id") && j.at("mission_id").is_string()) {
                        ptv_profile_set(world, entity_, "mission.last_completed", j.at("mission_id"));
                    }
                    ptv_save_now(world, entity_, "mission_complete");
                }
                if (j.value("unlock_purchase", false)) {
                    if (j.contains("unlock_id") && j.at("unlock_id").is_string()) {
                        auto cur = ptv_profile_get(world, entity_, "constructs.unlocked");
                        if (!cur.is_array()) cur = nlohmann::json::array();
                        cur.push_back(j.at("unlock_id"));
                        ptv_profile_set(world, entity_, "constructs.unlocked", cur);
                    }
                    ptv_save_now(world, entity_, "unlock_purchase");
                }
                if (j.value("recharge_complete", false)) {
                    ptv_save_now(world, entity_, "recharge_complete");
                }

                // Manual save request (e.g. from wrist HUD in hub scenes)
                if (j.value("manual_save", false)) {
                    ptv_save_now(world, entity_, "manual_save");
                }

                // Difficulty change
                if (j.contains("difficulty") && j.at("difficulty").is_string()) {
                    ptv_profile_set(world, entity_, "difficulty", j.at("difficulty"));
                    ptv_save_now(world, entity_, "difficulty_change");
                }

                // Accessibility flags
                if (j.contains("accessibility") && j.at("accessibility").is_object()) {
                    ptv_profile_set(world, entity_, "settings.options.accessibility", j.at("accessibility"));
                    ptv_save_now(world, entity_, "accessibility_change");
                }
            }
        }
    }

    void on_detach(World& world, std::uint32_t entity) override {
        // Final autosave on detach for safety.
        if (world.valid(entity)) ptv_save_now(world, entity, "detach_autosave");
        entity_ = 0;
    }

    std::string id() const override { return "generated.save_load_system"; }

private:
    // Local helpers reused from API TU via declarations below
    static std::optional<nlohmann::json> read_from_tag(World& world, std::uint32_t entity);
    static void mirror_into_tag(World& world, std::uint32_t entity, const nlohmann::json& blob);
    static nlohmann::json default_profile();

    std::uint32_t entity_{0};
};

// Forward declarations match those defined in save_load_system_api.cpp
static std::optional<nlohmann::json> read_from_tag(World& world, std::uint32_t entity);
static void mirror_into_tag(World& world, std::uint32_t entity, const nlohmann::json& blob);
static nlohmann::json default_profile();

PTV_REGISTER_MECHANIC("generated.save_load_system", SaveLoadSystem)

} // namespace ptv
